using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
using AlpineQuestPort;
class VisibilityTests {
 static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static T Field<T>(object obj,string name){return (T)obj.GetType().GetField(name,Flags).GetValue(obj);}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS: "+text);}
 static void Pump(int ms){var end=DateTime.UtcNow.AddMilliseconds(ms);while(DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(10);}}
 static void Shot(Control control,string path){using(var image=new Bitmap(control.Width,control.Height)){control.DrawToBitmap(image,control.ClientRectangle);image.Save(path);}}
 static void Seed(string root,VisibilityGrid grid){foreach(var tile in grid.Points.Select(p=>new {X=(int)(GeoMath.LonToPixel(p.Lon,14)/256),Y=(int)(GeoMath.LatToPixel(p.Lat,14)/256)}).Distinct()){
  string path=Path.Combine(root,"14",tile.X.ToString(),tile.Y+".png");Directory.CreateDirectory(Path.GetDirectoryName(path));using(var image=new Bitmap(256,256)){for(int y=0;y<256;y++)for(int x=0;x<256;x++){var p=new GeoPoint(GeoMath.PixelToLat(tile.Y*256+y,14),GeoMath.PixelToLon(tile.X*256+x,14));double d=GeoMath.DistanceMeters(grid.Origin,p),bearing=TerrainProfile.Bearing(grid.Origin,p)*Math.PI/180,east=d*Math.Sin(bearing),north=d*Math.Cos(bearing);double h=100+90*Math.Exp(-Math.Pow((east-350)/85,2))*Math.Exp(-Math.Pow(north/700,2));int encoded=(int)Math.Round((32768+h)*256);image.SetPixel(x,y,Color.FromArgb((encoded>>16)&255,(encoded>>8)&255,encoded&255));}image.Save(path,ImageFormat.Png);}
 }}
 [STAThread]static int Main(string[] args){try{Application.EnableVisualStyles();string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var o=new VisibilityOptions{Antenna=3,Drone=3,Frequency=1000,Curvature=false};double[] flat=Enumerable.Repeat(100.0,11).ToArray();
  Check(VisibilityGrid.Classify(flat,10,100,o)==VisibilityClass.FresnelBlocked,"flat terrain visible but Fresnel obstructed at 1 GHz");o.Frequency=10000;Check(VisibilityGrid.Classify(flat,10,100,o)==VisibilityClass.Clear,"higher frequency reduces Fresnel radius");o.Fresnel=false;o.Frequency=1000;Check(VisibilityGrid.Classify(flat,10,100,o)==VisibilityClass.Clear,"Fresnel toggle leaves geometric visibility");o.Fresnel=true;flat[5]=140;Check(VisibilityGrid.Classify(flat,10,100,o)==VisibilityClass.Blocked,"ridge blocks direct line");o.Drone=120;Check(VisibilityGrid.Classify(flat,10,100,o)==VisibilityClass.Clear,"raising drone clears ridge and Fresnel");flat[4]=double.NaN;Check(VisibilityGrid.Classify(flat,10,100,o)==VisibilityClass.Unknown,"missing intermediate terrain never becomes clear");flat[4]=100;flat[10]=250;o.AboveStart=true;o.Drone=50;Check(VisibilityGrid.Classify(flat,10,100,o)==VisibilityClass.Blocked,"height above start can place receiver below local terrain");
  flat=Enumerable.Repeat(100.0,11).ToArray();o=new VisibilityOptions{Antenna=2,Drone=2,Fresnel=false,Curvature=true};Check(VisibilityGrid.Classify(flat,10,2000,o)==VisibilityClass.Blocked,"Earth curvature obstructs low antennas over 20 km");o.Curvature=false;Check(VisibilityGrid.Classify(flat,10,2000,o)==VisibilityClass.Clear,"curvature can be disabled explicitly");
  var origin=new GeoPoint(46.57,8.4);o=new VisibilityOptions{Antenna=11,Drone=20,Radius=1000,Quality=1};var grid=VisibilityGrid.Create(origin,o,CancellationToken.None);Check(Math.Abs(GeoMath.DistanceMeters(origin,grid.Points.Last())-1000)<.001,"radial grid reaches exact requested radius");for(int i=0;i<grid.Heights.Length;i++)grid.Heights[i]=100;grid.Calculate(CancellationToken.None);Check(grid.Classes.Skip(1).All(s=>s==VisibilityClass.Clear),"flat full area clear");
  using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();bool stopped=false;try{grid.Calculate(cancelled.Token);}catch(OperationCanceledException){stopped=true;}Check(stopped,"background solver supports cancellation");}
  var random=new Random(36);var equivalence=VisibilityGrid.Create(origin,new VisibilityOptions{Radius=400,Quality=0},CancellationToken.None);equivalence.Heights[0]=100;for(int i=1;i<equivalence.Heights.Length;i++)equivalence.Heights[i]=random.Next(9)==0?double.NaN:80+random.Next(80);equivalence.Calculate(CancellationToken.None);bool same=true;for(int ray=0;ray<equivalence.Rays;ray++){var line=new double[equivalence.Steps+1];line[0]=equivalence.Heights[0];Array.Copy(equivalence.Heights,1+ray*equivalence.Steps,line,1,equivalence.Steps);for(int end=1;end<=equivalence.Steps;end++)if(equivalence.Classes[1+ray*equivalence.Steps+end-1]!=VisibilityGrid.Classify(line,end,equivalence.Step,equivalence.Options))same=false;}Check(same,"optimized missing-height scan matches per-path reference on random terrain");equivalence.Heights[0]=double.NaN;equivalence.Calculate(CancellationToken.None);Check(equivalence.Classes.Skip(1).All(v=>v==VisibilityClass.Unknown),"missing transmitter height invalidates all rays");
  var save=Path.Combine(root,"visibility.xml");o.Save(save);var loaded=VisibilityOptions.Load(save);Check(loaded.Frequency==o.Frequency&&loaded.Drone==o.Drone,"visibility settings persist");Seed(Path.Combine(root,"elevation-cache"),grid);
  using(var tiles=new TileStore(Path.Combine(root,"map-cache"),null))using(var map=new MapCanvas(tiles){Dock=DockStyle.Fill})using(var window=new Form{Size=new Size(1120,840)}){
   window.Controls.Add(map);map.Settings.Gpu=false;map.Settings.RangeRings=true;map.Settings.DataCards=false;map.Settings.RingStepMeters=500;map.GoTo(origin,15);window.Show();
   using(var form=new VisibilityForm(map,root)){
    form.Show(window);var task=form.StartCalculation();var until=DateTime.UtcNow.AddSeconds(30);while(DateTime.UtcNow<until&&map.VisibilityOverlay==null){Pump(30);}Check(map.VisibilityOverlay!=null,"offline DEM automatically produces visibility overlay");var finished=Field<VisibilityGrid>(form,"grid");Check(finished.Classes.Contains(VisibilityClass.Blocked)&&finished.Classes.Contains(VisibilityClass.Clear),"synthetic ridge creates shadow and clear sector");Check(finished.Classes.Skip(1).All(c=>c!=VisibilityClass.Unknown),"complete cached terrain has no unknown cells");Shot(form,Path.Combine(root,"visibility-settings.png"));Shot(map,Path.Combine(root,"visibility-map.png"));
    map.Settings.Perspective=true;map.Settings.Rotation=35;Shot(map,Path.Combine(root,"visibility-perspective.png"));Check(map.VisibilityOverlay!=null,"overlay renders under rotation and perspective");map.Settings.Perspective=false;map.Settings.Rotation=0;map.RequestFrame();Pump(800);
    using(var image=new Bitmap(map.Width,map.Height)){map.DrawToBitmap(image,map.ClientRectangle);var east=(PointF)typeof(MapCanvas).GetMethod("ToScreen",Flags).Invoke(map,new object[]{RangeRings.Destination(origin,650,90)});var west=(PointF)typeof(MapCanvas).GetMethod("ToScreen",Flags).Invoke(map,new object[]{RangeRings.Destination(origin,650,270)});var red=image.GetPixel((int)east.X,(int)east.Y);var green=image.GetPixel((int)west.X,(int)west.Y);Check(red.R>red.G&&green.G>green.R,"overlay colors remain geographically aligned east/west");}
    Field<Button>(form,"show").PerformClick();Check(!map.VisibilityShown,"hide overlay keeps calculation");Field<Button>(form,"show").PerformClick();Check(map.VisibilityShown,"show overlay restores result");Field<NumericUpDown>(form,"drone").Value=120;Check(map.VisibilityOverlay==null,"parameter change removes stale classification");Field<CheckBox>(form,"automatic").Checked=true;until=DateTime.UtcNow.AddSeconds(20);while(DateTime.UtcNow<until&&map.VisibilityOverlay==null)Pump(30);Check(map.VisibilityOverlay!=null,"debounced automatic calculation completes");    Field<CheckBox>(form,"automatic").Checked=false;Field<NumericUpDown>(form,"radius").Value=2000;var pending=form.StartCalculation();Field<Button>(form,"stop").PerformClick();Pump(500);Check(map.VisibilityOverlay==null,"cancelled generation cannot publish late results");form.Close();
   }map.SetVisibility(null);window.Close();
  }
  using(var tiles=new TileStore(Path.Combine(root,"empty-map"),null))using(var map=new MapCanvas(tiles))using(var form=new VisibilityForm(map,Path.Combine(root,"empty"))){map.GoTo(origin,15);form.Show();var task=form.StartCalculation();var until=DateTime.UtcNow.AddSeconds(15);while(DateTime.UtcNow<until&&map.VisibilityOverlay==null)Pump(30);Check(map.VisibilityOverlay!=null&&Field<VisibilityGrid>(form,"grid").Classes.Skip(1).All(c=>c==VisibilityClass.Unknown),"missing offline DEM shows unknown instead of false clear");form.Close();map.SetVisibility(null);}
  Console.WriteLine("ALL VISIBILITY TESTS PASSED");return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}



